from itertools import combinations
count = 0
for ups in combinations(range(12), 6):
    x = y = 0
    ok = True
    for i in range(12):
        if i in ups:
            y += 1
        else:
            x += 1
        if y > x:
            ok = False
            break
    count += ok
print(count)
